INSERT INTO public.packages (name,slug,category,description,duration_minutes,total_questions,is_free,is_published)
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Gaya dalam yang bekerja sejajar dengan penampang balok dan cenderung menggeser satu bagian terhadap bagian lainnya disebut...','[{"key": "A", "text": "Momen lentur"}, {"key": "B", "text": "Gaya aksial"}, {"key": "C", "text": "Gaya geser"}, {"key": "D", "text": "Torsi"}]'::jsonb,'A','Dalam analisis struktur, gaya geser (shear force) merupakan gaya internal yang bekerja sejajar dengan penampang potongan suatu elemen, seperti balok. Gaya ini muncul sebagai reaksi terhadap beban eksternal dan memiliki kecenderungan untuk menyebabkan satu bagian dari elemen tersebut bergeser relatif terhadap bagian lainnya. Ini berbeda dari momen lentur yang membengkokkan atau gaya aksial yang menekan/menarik elemen.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada sebuah balok sederhana (simple beam) yang menahan beban terdistribusi merata, momen lentur maksimum terjadi di...','[{"key": "A", "text": "Tumpuan kiri"}, {"key": "B", "text": "Tumpuan kanan"}, {"key": "C", "text": "Tengah bentang"}, {"key": "D", "text": "Seperempat bentang"}]'::jsonb,'A','Untuk balok sederhana yang ditumpu di kedua ujungnya dan menerima beban terdistribusi merata, diagram gaya geser akan berbentuk linier dan bernilai nol tepat di tengah bentang. Titik di mana gaya geser bernilai nol merupakan lokasi di mana momen lentur mencapai nilai maksimumnya. Diagram momen untuk kasus ini akan membentuk kurva parabola yang puncaknya berada di tengah bentang.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Elemen struktur yang dirancang untuk menahan beban tekan aksial secara dominan adalah...','[{"key": "A", "text": "Balok"}, {"key": "B", "text": "Kolom"}, {"key": "C", "text": "Pelat"}, {"key": "D", "text": "Fondasi"}]'::jsonb,'A','Kolom adalah elemen struktur vertikal yang fungsi utamanya adalah untuk menopang beban tekan yang bekerja searah dengan sumbunya (aksial). Beban ini biasanya berasal dari balok, pelat lantai, atau atap di atasnya, yang kemudian disalurkan oleh kolom ke sistem pondasi.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Asumsi utama dalam analisis struktur rangka batang (truss) sederhana adalah...','[{"key": "A", "text": "Sambungan bersifat kaku (rigid)"}, {"key": "B", "text": "Beban bekerja di sepanjang batang"}, {"key": "C", "text": "Sambungan dianggap sebagai sendi (pin-jointed)"}, {"key": "D", "text": "Batang dapat menahan momen lentur"}]'::jsonb,'A','Analisis struktur rangka batang (truss) yang disederhanakan didasarkan pada beberapa asumsi ideal. Asumsi yang paling fundamental adalah bahwa semua sambungan antar batang adalah sambungan sendi (pin) yang dapat berotasi bebas. Ini berarti sambungan tidak dapat menahan momen lentur, sehingga setiap batang dalam struktur hanya akan mengalami gaya aksial murni, yaitu gaya tarik atau gaya tekan.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Selain berat sendiri, beban dominan yang harus diperhitungkan dalam desain struktur menara transmisi listrik (tower) adalah...','[{"key": "A", "text": "Beban gempa"}, {"key": "B", "text": "Beban angin"}, {"key": "C", "text": "Beban hujan"}, {"key": "D", "text": "Beban hidup (manusia)"}]'::jsonb,'A','Menara transmisi listrik merupakan struktur yang tinggi dan relatif ramping dengan luas permukaan yang signifikan. Karena karakteristik geometrinya, menara ini sangat rentan terhadap gaya lateral yang disebabkan oleh angin. Oleh karena itu, dalam perancangan struktur menara, beban angin menjadi salah satu beban dominan yang harus dianalisis secara cermat untuk memastikan stabilitas dan keamanan struktur.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Besaran yang didefinisikan sebagai hasil kali gaya dengan jarak tegak lurus dari titik acuan ke garis kerja gaya disebut...','[{"key": "A", "text": "Momen"}, {"key": "B", "text": "Impuls"}, {"key": "C", "text": "Energi"}, {"key": "D", "text": "Daya"}]'::jsonb,'A','Momen (sering juga disebut momen gaya atau torsi) adalah suatu besaran fisika yang mengukur kecenderungan sebuah gaya untuk memutar suatu benda di sekitar titik atau sumbu tertentu. Besarnya momen dihitung dengan mengalikan besar gaya (F) dengan jarak tegak lurus (d) dari titik acuan ke garis kerja gaya tersebut (M = F × d).','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada balok kantilever yang diberi beban terpusat di ujung bebasnya, di manakah letak gaya geser maksimum?','[{"key": "A", "text": "Di ujung bebas"}, {"key": "B", "text": "Di tengah bentang"}, {"key": "C", "text": "Di seluruh panjang balok"}, {"key": "D", "text": "Di tumpuan jepit"}]'::jsonb,'A','Balok kantilever adalah balok yang salah satu ujungnya tertumpu jepit dan ujung lainnya bebas. Ketika beban terpusat bekerja di ujung bebas, gaya tersebut harus disalurkan sepenuhnya ke tumpuan jepit. Akibatnya, gaya geser akan memiliki nilai konstan yang sama dengan besar beban di seluruh panjang balok, mulai dari ujung bebas hingga tumpuan. Dengan demikian, nilai gaya geser maksimum berada di sepanjang balok, termasuk di tumpuan jepitnya.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi utama baja tulangan pada struktur beton bertulang adalah untuk menahan...','[{"key": "A", "text": "Gaya tekan"}, {"key": "B", "text": "Gaya tarik"}, {"key": "C", "text": "Gaya geser"}, {"key": "D", "text": "Beban kejut"}]'::jsonb,'A','','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Istilah "mutu beton K-300" mengacu pada kekuatan tekan karakteristik beton yang diuji menggunakan benda uji berbentuk kubus pada umur...','[{"key": "A", "text": "7 hari"}, {"key": "B", "text": "14 hari"}, {"key": "C", "text": "21 hari"}, {"key": "D", "text": "28 hari"}]'::jsonb,'A','Beton adalah material yang sangat kuat dalam menahan beban tekan, tetapi sangat lemah ketika menahan beban tarik. Untuk mengatasi kelemahan ini, baja tulangan ditanamkan di dalam beton. Saat struktur beton (seperti balok) melentur, akan timbul tegangan tekan di satu sisi dan tegangan tarik di sisi lain. Beton akan menahan tekan, sementara baja tulangan akan secara efektif menahan gaya tarik.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam struktur balok beton bertulang, tulangan sengkang (stirrup) dipasang terutama untuk menahan...','[{"key": "A", "text": "Momen lentur positif"}, {"key": "B", "text": "Momen lentur negatif"}, {"key": "C", "text": "Gaya geser"}, {"key": "D", "text": "Torsi"}]'::jsonb,'A','Standar industri konstruksi menetapkan bahwa pengujian kekuatan tekan beton dilakukan pada umur 28 hari setelah pengecoran. Ini didasarkan pada fakta bahwa proses hidrasi semen, yaitu reaksi kimia yang menyebabkan pengerasan beton, telah mencapai sebagian besar kekuatannya pada titik ini. Kekuatan yang diukur pada umur 28 hari ini kemudian dijadikan sebagai kekuatan acuan (karakteristik) dalam desain struktur.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Salah satu keunggulan utama baja sebagai material struktur dibandingkan beton adalah...','[{"key": "A", "text": "Tahan terhadap api"}, {"key": "B", "text": "Rasio kekuatan terhadap berat yang tinggi"}, {"key": "C", "text": "Biaya material yang lebih murah"}, {"key": "D", "text": "Tahan terhadap korosi tanpa pelapis"}]'::jsonb,'A','Dalam balok beton bertulang, tulangan sengkang (juga dikenal sebagai stirrup) dipasang secara vertikal atau miring, melingkari tulangan utama (longitudinal). Fungsi utamanya adalah untuk menahan gaya geser yang dapat menyebabkan retak diagonal pada balok. Selain itu, sengkang juga berfungsi untuk mengikat tulangan utama agar tetap pada posisinya dan memberikan kekangan pada inti beton.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam tiang beton untuk jaringan listrik PLN, kombinasi material beton dan baja dimanfaatkan di mana...','[{"key": "A", "text": "Beton menahan tarik, baja menahan tekan"}, {"key": "B", "text": "Beton menahan tekan, baja menahan tarik"}, {"key": "C", "text": "Keduanya bersama-sama menahan tekan"}, {"key": "D", "text": "Keduanya bersama-sama menahan tarik"}]'::jsonb,'A','Salah satu keunggulan teknis baja yang paling menonjol adalah rasio kekuatan terhadap beratnya yang sangat tinggi. Ini berarti baja dapat menahan beban yang sangat besar dengan dimensi penampang yang relatif kecil dan berat yang ringan. Keunggulan ini memungkinkan perancangan struktur bentang panjang, bangunan tinggi, dan elemen yang lebih ramping dibandingkan jika menggunakan material lain seperti beton.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses pemadatan beton segar bertujuan untuk...','[{"key": "A", "text": "Mempercepat proses pengeringan"}, {"key": "B", "text": "Mengeluarkan udara yang terperangkap"}, {"key": "C", "text": "Menambah volume beton"}, {"key": "D", "text": "Menurunkan suhu hidrasi"}]'::jsonb,'A','Prinsip kerja komposit antara beton dan baja pada tiang listrik sama dengan struktur beton bertulang lainnya. Ketika tiang mengalami lenturan akibat beban seperti angin, satu sisi akan mengalami tegangan tekan yang ditahan oleh kekuatan beton. Sisi sebaliknya akan mengalami tegangan tarik yang sepenuhnya ditahan oleh baja tulangan di dalamnya, karena beton sangat lemah terhadap tarik.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Faktor utama yang dapat menyebabkan korosi pada baja tulangan di dalam beton adalah...','[{"key": "A", "text": "Suhu beton yang terlalu tinggi"}, {"key": "B", "text": "Agregat yang terlalu kasar"}, {"key": "C", "text": "Karbonasi atau intrusi ion klorida"}, {"key": "D", "text": "Beban berlebih pada struktur"}]'::jsonb,'A','Selama proses pencampuran dan pengecoran, udara dapat terperangkap dalam adukan beton segar dan membentuk rongga-rongga udara. Proses pemadatan, biasanya menggunakan alat penggetar (vibrator), bertujuan untuk mengeluarkan gelembung udara ini. Hasilnya adalah beton yang lebih padat, homogen, tidak keropos, dan mampu mencapai kekuatan serta durabilitas sesuai rencana.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses penurunan volume tanah berbutir halus (seperti lempung) akibat keluarnya air pori secara perlahan karena pembebanan disebut...','[{"key": "A", "text": "Kompaksi"}, {"key": "B", "text": "Likuefaksi"}, {"key": "C", "text": "Konsolidasi"}, {"key": "D", "text": "Erosi"}]'::jsonb,'A','Baja tulangan di dalam beton dilindungi dari korosi oleh lapisan pasif tipis yang terbentuk karena sifat basa (alkali) dari beton. Perlindungan ini bisa hilang jika terjadi karbonasi (reaksi CO2 dari udara dengan beton yang menurunkan pH) atau jika ion agresif seperti klorida (biasanya dari lingkungan laut atau garam) meresap ke dalam beton. Ketika lapisan pasif ini rusak, baja tulangan akan mulai berkarat.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut kriteria keruntuhan Mohr-Coulomb, kekuatan geser tanah ditentukan oleh dua parameter utama, yaitu...','[{"key": "A", "text": "Kepadatan dan kadar air"}, {"key": "B", "text": "Kohesi dan sudut geser dalam"}, {"key": "C", "text": "Permeabilitas dan kompresibilitas"}, {"key": "D", "text": "Angka pori dan batas plastis"}]'::jsonb,'A','','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kapasitas dukung ultimit (ultimate bearing capacity) sebuah pondasi adalah...','[{"key": "A", "text": "Tegangan maksimum yang dapat ditahan tanah sebelum runtuh"}, {"key": "B", "text": "Tegangan yang menyebabkan penurunan sebesar 25 mm"}, {"key": "C", "text": "Beban kerja aman yang diizinkan pada pondasi"}, {"key": "D", "text": "Beban total struktur yang dipikul pondasi"}]'::jsonb,'A','Konsolidasi adalah proses yang spesifik terjadi pada tanah berbutir halus dan jenuh air seperti lempung. Ketika beban diterapkan, tekanan pada air di dalam pori-pori tanah meningkat. Karena permeabilitas lempung sangat rendah, air membutuhkan waktu lama untuk keluar dari pori-pori. Proses keluarnya air secara perlahan inilah yang menyebabkan penurunan volume tanah secara bertahap dalam jangka waktu yang panjang.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pondasi tiang pancang (pile foundation) umumnya digunakan pada kondisi tanah di mana...','[{"key": "A", "text": "Lapisan tanah atas sangat keras dan padat"}, {"key": "B", "text": "Lapisan tanah atas lunak dengan daya dukung rendah"}, {"key": "C", "text": "Muka air tanah sangat dalam"}, {"key": "D", "text": "Tanah berupa batuan masif"}]'::jsonb,'A','Kriteria keruntuhan Mohr-Coulomb adalah model fundamental untuk mendefinisikan kekuatan geser tanah. Menurut model ini, kekuatan tanah terdiri dari dua komponen: kohesi (c), yang merupakan daya lekat intrinsik antar partikel tanah (dominan pada lempung), dan sudut geser dalam (φ), yang merepresentasikan tahanan gesek antar partikel (dominan pada pasir).','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk pondasi tower transmisi di lokasi tanah rawa yang lunak, jenis pondasi yang paling sesuai adalah...','[{"key": "A", "text": "Pondasi dangkal telapak"}, {"key": "B", "text": "Pondasi sumuran"}, {"key": "C", "text": "Pondasi tiang pancang"}, {"key": "D", "text": "Pondasi umpak batu kali"}]'::jsonb,'A','Kapasitas dukung ultimit adalah tegangan kontak maksimum teoretis yang dapat diberikan oleh pondasi ke tanah di bawahnya sebelum tanah tersebut mengalami keruntuhan geser (shear failure). Dalam praktik desain, nilai ultimit ini akan dibagi dengan suatu Faktor Keamanan (biasanya 2.5 hingga 3) untuk mendapatkan kapasitas dukung izin (allowable) yang aman untuk digunakan.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Uji Standard Penetration Test (SPT) di lapangan bertujuan untuk memperoleh nilai N-SPT yang mengindikasikan...','[{"key": "A", "text": "Kadar air tanah"}, {"key": "B", "text": "Kepadatan relatif atau konsistensi tanah"}, {"key": "C", "text": "Permeabilitas tanah"}, {"key": "D", "text": "Berat volume tanah"}]'::jsonb,'A','Pondasi tiang pancang atau tiang bor termasuk dalam kategori pondasi dalam. Jenis pondasi ini digunakan ketika lapisan tanah permukaan tidak cukup kuat untuk menopang beban struktur. Tujuannya adalah untuk mentransfer beban dari struktur atas menembus lapisan tanah yang lunak tersebut menuju lapisan tanah yang lebih dalam yang lebih keras dan memiliki kapasitas dukung yang jauh lebih tinggi.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Gaya dalam yang bekerja sejajar dengan penampang balok dan cenderung menggeser satu bagian terhadap bagian lainnya disebut...','[{"key": "A", "text": "Momen lentur"}, {"key": "B", "text": "Gaya aksial"}, {"key": "C", "text": "Gaya geser"}, {"key": "D", "text": "Torsi"}]'::jsonb,'A','Dalam analisis struktur, gaya geser (shear force) merupakan gaya internal yang bekerja sejajar dengan penampang potongan suatu elemen, seperti balok. Gaya ini muncul sebagai reaksi terhadap beban eksternal dan memiliki kecenderungan untuk menyebabkan satu bagian dari elemen tersebut bergeser relatif terhadap bagian lainnya. Ini berbeda dari momen lentur yang membengkokkan atau gaya aksial yang menekan/menarik elemen.','AKDING',1);
