  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada balok kantilever yang diberi beban terpusat di ujung bebasnya, di manakah letak gaya geser maksimum?','[{"key": "A", "text": "Di ujung bebas"}, {"key": "B", "text": "Di tengah bentang"}, {"key": "C", "text": "Di seluruh panjang balok"}, {"key": "D", "text": "Di tumpuan jepit"}]'::jsonb,'A','Balok kantilever adalah balok yang salah satu ujungnya tertumpu jepit dan ujung lainnya bebas. Ketika beban terpusat bekerja di ujung bebas, gaya tersebut harus disalurkan sepenuhnya ke tumpuan jepit. Akibatnya, gaya geser akan memiliki nilai konstan yang sama dengan besar beban di seluruh panjang balok, mulai dari ujung bebas hingga tumpuan. Dengan demikian, nilai gaya geser maksimum berada di sepanjang balok, termasuk di tumpuan jepitnya.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi utama baja tulangan pada struktur beton bertulang adalah untuk menahan...','[{"key": "A", "text": "Gaya tekan"}, {"key": "B", "text": "Gaya tarik"}, {"key": "C", "text": "Gaya geser"}, {"key": "D", "text": "Beban kejut"}]'::jsonb,'A','','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Istilah "mutu beton K-300" mengacu pada kekuatan tekan karakteristik beton yang diuji menggunakan benda uji berbentuk kubus pada umur...','[{"key": "A", "text": "7 hari"}, {"key": "B", "text": "14 hari"}, {"key": "C", "text": "21 hari"}, {"key": "D", "text": "28 hari"}]'::jsonb,'A','Beton adalah material yang sangat kuat dalam menahan beban tekan, tetapi sangat lemah ketika menahan beban tarik. Untuk mengatasi kelemahan ini, baja tulangan ditanamkan di dalam beton. Saat struktur beton (seperti balok) melentur, akan timbul tegangan tekan di satu sisi dan tegangan tarik di sisi lain. Beton akan menahan tekan, sementara baja tulangan akan secara efektif menahan gaya tarik.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam struktur balok beton bertulang, tulangan sengkang (stirrup) dipasang terutama untuk menahan...','[{"key": "A", "text": "Momen lentur positif"}, {"key": "B", "text": "Momen lentur negatif"}, {"key": "C", "text": "Gaya geser"}, {"key": "D", "text": "Torsi"}]'::jsonb,'A','Standar industri konstruksi menetapkan bahwa pengujian kekuatan tekan beton dilakukan pada umur 28 hari setelah pengecoran. Ini didasarkan pada fakta bahwa proses hidrasi semen, yaitu reaksi kimia yang menyebabkan pengerasan beton, telah mencapai sebagian besar kekuatannya pada titik ini. Kekuatan yang diukur pada umur 28 hari ini kemudian dijadikan sebagai kekuatan acuan (karakteristik) dalam desain struktur.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Salah satu keunggulan utama baja sebagai material struktur dibandingkan beton adalah...','[{"key": "A", "text": "Tahan terhadap api"}, {"key": "B", "text": "Rasio kekuatan terhadap berat yang tinggi"}, {"key": "C", "text": "Biaya material yang lebih murah"}, {"key": "D", "text": "Tahan terhadap korosi tanpa pelapis"}]'::jsonb,'A','Dalam balok beton bertulang, tulangan sengkang (juga dikenal sebagai stirrup) dipasang secara vertikal atau miring, melingkari tulangan utama (longitudinal). Fungsi utamanya adalah untuk menahan gaya geser yang dapat menyebabkan retak diagonal pada balok. Selain itu, sengkang juga berfungsi untuk mengikat tulangan utama agar tetap pada posisinya dan memberikan kekangan pada inti beton.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam tiang beton untuk jaringan listrik PLN, kombinasi material beton dan baja dimanfaatkan di mana...','[{"key": "A", "text": "Beton menahan tarik, baja menahan tekan"}, {"key": "B", "text": "Beton menahan tekan, baja menahan tarik"}, {"key": "C", "text": "Keduanya bersama-sama menahan tekan"}, {"key": "D", "text": "Keduanya bersama-sama menahan tarik"}]'::jsonb,'A','Salah satu keunggulan teknis baja yang paling menonjol adalah rasio kekuatan terhadap beratnya yang sangat tinggi. Ini berarti baja dapat menahan beban yang sangat besar dengan dimensi penampang yang relatif kecil dan berat yang ringan. Keunggulan ini memungkinkan perancangan struktur bentang panjang, bangunan tinggi, dan elemen yang lebih ramping dibandingkan jika menggunakan material lain seperti beton.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses pemadatan beton segar bertujuan untuk...','[{"key": "A", "text": "Mempercepat proses pengeringan"}, {"key": "B", "text": "Mengeluarkan udara yang terperangkap"}, {"key": "C", "text": "Menambah volume beton"}, {"key": "D", "text": "Menurunkan suhu hidrasi"}]'::jsonb,'A','Prinsip kerja komposit antara beton dan baja pada tiang listrik sama dengan struktur beton bertulang lainnya. Ketika tiang mengalami lenturan akibat beban seperti angin, satu sisi akan mengalami tegangan tekan yang ditahan oleh kekuatan beton. Sisi sebaliknya akan mengalami tegangan tarik yang sepenuhnya ditahan oleh baja tulangan di dalamnya, karena beton sangat lemah terhadap tarik.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Faktor utama yang dapat menyebabkan korosi pada baja tulangan di dalam beton adalah...','[{"key": "A", "text": "Suhu beton yang terlalu tinggi"}, {"key": "B", "text": "Agregat yang terlalu kasar"}, {"key": "C", "text": "Karbonasi atau intrusi ion klorida"}, {"key": "D", "text": "Beban berlebih pada struktur"}]'::jsonb,'A','Selama proses pencampuran dan pengecoran, udara dapat terperangkap dalam adukan beton segar dan membentuk rongga-rongga udara. Proses pemadatan, biasanya menggunakan alat penggetar (vibrator), bertujuan untuk mengeluarkan gelembung udara ini. Hasilnya adalah beton yang lebih padat, homogen, tidak keropos, dan mampu mencapai kekuatan serta durabilitas sesuai rencana.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses penurunan volume tanah berbutir halus (seperti lempung) akibat keluarnya air pori secara perlahan karena pembebanan disebut...','[{"key": "A", "text": "Kompaksi"}, {"key": "B", "text": "Likuefaksi"}, {"key": "C", "text": "Konsolidasi"}, {"key": "D", "text": "Erosi"}]'::jsonb,'A','Baja tulangan di dalam beton dilindungi dari korosi oleh lapisan pasif tipis yang terbentuk karena sifat basa (alkali) dari beton. Perlindungan ini bisa hilang jika terjadi karbonasi (reaksi CO2 dari udara dengan beton yang menurunkan pH) atau jika ion agresif seperti klorida (biasanya dari lingkungan laut atau garam) meresap ke dalam beton. Ketika lapisan pasif ini rusak, baja tulangan akan mulai berkarat.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut kriteria keruntuhan Mohr-Coulomb, kekuatan geser tanah ditentukan oleh dua parameter utama, yaitu...','[{"key": "A", "text": "Kepadatan dan kadar air"}, {"key": "B", "text": "Kohesi dan sudut geser dalam"}, {"key": "C", "text": "Permeabilitas dan kompresibilitas"}, {"key": "D", "text": "Angka pori dan batas plastis"}]'::jsonb,'A','','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kapasitas dukung ultimit (ultimate bearing capacity) sebuah pondasi adalah...','[{"key": "A", "text": "Tegangan maksimum yang dapat ditahan tanah sebelum runtuh"}, {"key": "B", "text": "Tegangan yang menyebabkan penurunan sebesar 25 mm"}, {"key": "C", "text": "Beban kerja aman yang diizinkan pada pondasi"}, {"key": "D", "text": "Beban total struktur yang dipikul pondasi"}]'::jsonb,'A','Konsolidasi adalah proses yang spesifik terjadi pada tanah berbutir halus dan jenuh air seperti lempung. Ketika beban diterapkan, tekanan pada air di dalam pori-pori tanah meningkat. Karena permeabilitas lempung sangat rendah, air membutuhkan waktu lama untuk keluar dari pori-pori. Proses keluarnya air secara perlahan inilah yang menyebabkan penurunan volume tanah secara bertahap dalam jangka waktu yang panjang.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pondasi tiang pancang (pile foundation) umumnya digunakan pada kondisi tanah di mana...','[{"key": "A", "text": "Lapisan tanah atas sangat keras dan padat"}, {"key": "B", "text": "Lapisan tanah atas lunak dengan daya dukung rendah"}, {"key": "C", "text": "Muka air tanah sangat dalam"}, {"key": "D", "text": "Tanah berupa batuan masif"}]'::jsonb,'A','Kriteria keruntuhan Mohr-Coulomb adalah model fundamental untuk mendefinisikan kekuatan geser tanah. Menurut model ini, kekuatan tanah terdiri dari dua komponen: kohesi (c), yang merupakan daya lekat intrinsik antar partikel tanah (dominan pada lempung), dan sudut geser dalam (φ), yang merepresentasikan tahanan gesek antar partikel (dominan pada pasir).','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk pondasi tower transmisi di lokasi tanah rawa yang lunak, jenis pondasi yang paling sesuai adalah...','[{"key": "A", "text": "Pondasi dangkal telapak"}, {"key": "B", "text": "Pondasi sumuran"}, {"key": "C", "text": "Pondasi tiang pancang"}, {"key": "D", "text": "Pondasi umpak batu kali"}]'::jsonb,'A','Kapasitas dukung ultimit adalah tegangan kontak maksimum teoretis yang dapat diberikan oleh pondasi ke tanah di bawahnya sebelum tanah tersebut mengalami keruntuhan geser (shear failure). Dalam praktik desain, nilai ultimit ini akan dibagi dengan suatu Faktor Keamanan (biasanya 2.5 hingga 3) untuk mendapatkan kapasitas dukung izin (allowable) yang aman untuk digunakan.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Uji Standard Penetration Test (SPT) di lapangan bertujuan untuk memperoleh nilai N-SPT yang mengindikasikan...','[{"key": "A", "text": "Kadar air tanah"}, {"key": "B", "text": "Kepadatan relatif atau konsistensi tanah"}, {"key": "C", "text": "Permeabilitas tanah"}, {"key": "D", "text": "Berat volume tanah"}]'::jsonb,'A','Pondasi tiang pancang atau tiang bor termasuk dalam kategori pondasi dalam. Jenis pondasi ini digunakan ketika lapisan tanah permukaan tidak cukup kuat untuk menopang beban struktur. Tujuannya adalah untuk mentransfer beban dari struktur atas menembus lapisan tanah yang lunak tersebut menuju lapisan tanah yang lebih dalam yang lebih keras dan memiliki kapasitas dukung yang jauh lebih tinggi.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari pekerjaan pemadatan tanah (soil compaction) adalah untuk...','[{"key": "A", "text": "Meningkatkan permeabilitas tanah"}, {"key": "B", "text": "Menurunkan berat volume tanah"}, {"key": "C", "text": "Meningkatkan kepadatan dan kekuatan geser tanah"}, {"key": "D", "text": "Menambah kadar air optimum"}]'::jsonb,'A','Tanah rawa umumnya memiliki daya dukung yang sangat rendah dan sangat kompresibel (mudah mampat). Pondasi dangkal tidak akan mampu menahan beban besar dari tower transmisi. Oleh karena itu, diperlukan sistem pondasi dalam seperti pondasi tiang pancang untuk menyalurkan beban tower ke lapisan tanah yang lebih kompeten dan stabil di kedalaman yang lebih besar.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Gaya penggerak utama pada aliran air di saluran terbuka (open-channel flow) adalah...','[{"key": "A", "text": "Tekanan"}, {"key": "B", "text": "Gravitasi"}, {"key": "C", "text": "Viskositas"}, {"key": "D", "text": "Kecepatan angin"}]'::jsonb,'A','Uji SPT mengukur jumlah pukulan (N) yang diperlukan untuk memasukkan sampler tabung belah sedalam 30 cm ke dalam tanah. Nilai N-SPT ini secara empiris berkorelasi kuat dengan sifat-sifat tanah. Untuk tanah pasir, nilai N-SPT mengindikasikan kepadatan relatifnya (misalnya, lepas, sedang, padat). Untuk tanah lempung, nilai ini mengindikasikan konsistensinya (misalnya, lunak, sedang, keras).','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Debit aliran (discharge) dalam sebuah saluran didefinisikan sebagai...','[{"key": "A", "text": "Kecepatan aliran dikalikan dengan luas penampang basah"}, {"key": "B", "text": "Luas penampang basah dibagi kecepatan aliran"}, {"key": "C", "text": "Keliling basah dikalikan dengan kemiringan dasar saluran"}, {"key": "D", "text": "Kedalaman air dibagi dengan lebar saluran"}]'::jsonb,'A','Pekerjaan pemadatan tanah adalah proses rekayasa untuk meningkatkan kepadatan tanah dengan cara mengurangi volume rongga udara di dalamnya, biasanya dengan menggunakan energi mekanis (misalnya, roller atau stamper). Dengan meningkatnya kepadatan, partikel tanah menjadi lebih rapat, yang secara langsung meningkatkan kekuatan geser, mengurangi potensi penurunan (settlement), dan menurunkan kemampuan air untuk meresap (permeabilitas).','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Berdasarkan persamaan Manning, jika kekasaran dasar sebuah kanal PLTA meningkat, maka kecepatan aliran air akan...','[{"key": "A", "text": "Meningkat"}, {"key": "B", "text": "Menurun"}, {"key": "C", "text": "Tetap konstan"}, {"key": "D", "text": "Menjadi nol"}]'::jsonb,'A','','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi utama tanggul pada sistem drainase atau sungai adalah...','[{"key": "A", "text": "Mengarahkan aliran air ke turbin"}, {"key": "B", "text": "Mencegah terjadinya luapan air atau banjir"}, {"key": "C", "text": "Menjadi tempat rekreasi"}, {"key": "D", "text": "Menyaring kotoran dari aliran air"}]'::jsonb,'A','Berbeda dengan aliran dalam pipa yang digerakkan oleh perbedaan tekanan, aliran di saluran terbuka (seperti sungai atau kanal) terjadi karena adanya kemiringan dasar saluran. Komponen gaya gravitasi yang sejajar dengan kemiringan dasar inilah yang menjadi gaya pendorong utama yang membuat air mengalir, mengatasi gaya gesek dari dasar dan dinding saluran.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam proyek PLTA, kanal yang berfungsi mengalirkan air dari bendungan (waduk) menuju pipa pesat (penstock) disebut...','[{"key": "A", "text": "Saluran pembuang (tailrace)"}, {"key": "B", "text": "Saluran pembawa (headrace)"}, {"key": "C", "text": "Saluran pelimpah (spillway)"}, {"key": "D", "text": "Saluran irigasi"}]'::jsonb,'A','Debit aliran (Q) adalah volume fluida yang melewati suatu penampang per satuan waktu. Ini dihitung menggunakan persamaan kontinuitas dasar: Q = V × A, di mana V adalah kecepatan rata-rata aliran yang melewati penampang, dan A adalah luas penampang basah (area penampang saluran yang terisi air).','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Bilangan Froude (Froude Number) digunakan untuk mengklasifikasikan jenis aliran. Aliran disebut superkritis jika nilai Bilangan Froude...','[{"key": "A", "text": "Fr < 1"}, {"key": "B", "text": "Fr = 1"}, {"key": "C", "text": "Fr > 1"}, {"key": "D", "text": "Fr = 0"}]'::jsonb,'A','Persamaan Manning (V = (1/n) * R^(2/3) * S^(1/2)) menunjukkan hubungan antara kecepatan aliran (V) dengan koefisien kekasaran Manning (n). Terlihat bahwa kecepatan berbanding terbalik dengan koefisien kekasaran. Artinya, jika permukaan dasar kanal menjadi lebih kasar (misalnya karena ada vegetasi atau sedimen), nilai ''n'' akan meningkat, yang menyebabkan peningkatan gesekan dan akibatnya kecepatan aliran akan menurun.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dua komponen utama yang digunakan untuk menghitung Rencana Anggaran Biaya (RAB) suatu pekerjaan konstruksi adalah...','[{"key": "A", "text": "Durasi proyek dan jumlah pekerja"}, {"key": "B", "text": "Volume pekerjaan dan harga satuan pekerjaan"}, {"key": "C", "text": "Jadwal proyek dan spesifikasi teknis"}, {"key": "D", "text": "Gambar kerja dan metode pelaksanaan"}]'::jsonb,'A','Tanggul adalah bangunan hidraulik yang dibuat sejajar dengan tepi sungai atau kanal, dengan elevasi puncak yang lebih tinggi dari muka air banjir rencana. Fungsi utamanya adalah untuk menahan aliran air agar tetap berada di dalam alur sungai atau kanal selama terjadi debit tinggi, sehingga mencegah air meluap ke daerah sekitarnya dan menyebabkan banjir.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kurva S dalam manajemen proyek konstruksi menggambarkan hubungan antara...','[{"key": "A", "text": "Biaya dan mutu"}, {"key": "B", "text": "Waktu dan jumlah pekerja"}, {"key": "C", "text": "Akumulasi kemajuan pekerjaan (progress) dan waktu"}, {"key": "D", "text": "Risiko dan durasi proyek"}]'::jsonb,'A','Dalam sistem PLTA, saluran pembawa atau headrace canal adalah kanal yang berfungsi untuk mengalirkan air dari titik pengambilan (intake) di waduk menuju bangunan di mana pipa pesat (penstock) dimulai. Saluran ini dirancang untuk meminimalkan kehilangan energi (head loss) agar air tiba di turbin dengan energi potensial semaksimal mungkin.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam metode jalur kritis (Critical Path Method - CPM), jalur kritis adalah...','[{"key": "A", "text": "Rangkaian kegiatan terpendek dalam proyek"}, {"key": "B", "text": "Rangkaian kegiatan dengan biaya paling murah"}, {"key": "C", "text": "Rangkaian kegiatan dengan total float (slack) sama dengan nol"}, {"key": "D", "text": "Rangkaian kegiatan yang bisa ditunda tanpa mempengaruhi durasi proyek"}]'::jsonb,'A','Bilangan Froude adalah parameter tak berdimensi yang membandingkan gaya inersia aliran dengan gaya gravitasi. Jika Fr > 1, itu berarti gaya inersia lebih dominan, menghasilkan aliran yang cepat dan dangkal yang disebut aliran superkritis. Sebaliknya, jika Fr < 1, gaya gravitasi lebih dominan, menghasilkan aliran yang tenang dan dalam yang disebut subkritis.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Saat melakukan estimasi biaya pembangunan gardu induk, salah satu komponen biaya pekerjaan sipil yang paling signifikan adalah...','[{"key": "A", "text": "Biaya arsitektur dan finishing"}, {"key": "B", "text": "Biaya pembuatan pagar pengaman"}, {"key": "C", "text": "Biaya pondasi untuk peralatan dan gedung kontrol"}, {"key": "D", "text": "Biaya lansekap dan taman"}]'::jsonb,'A','','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Metode penjadwalan proyek yang menggunakan tiga estimasi waktu (optimis, paling mungkin, pesimis) untuk setiap kegiatan adalah...','[{"key": "A", "text": "CPM (Critical Path Method)"}, {"key": "B", "text": "GANTT Chart"}, {"key": "C", "text": "PERT (Program Evaluation and Review Technique)"}, {"key": "D", "text": "WBS (Work Breakdown Structure)"}]'::jsonb,'A','Penyusunan Rencana Anggaran Biaya (RAB) dilakukan melalui dua langkah utama. Pertama, menghitung volume atau kuantitas setiap item pekerjaan berdasarkan gambar desain (misalnya, volume galian dalam m³, luas plesteran dalam m²). Kedua, mengalikan volume tersebut dengan harga satuan pekerjaan yang sesuai, yang didapat dari analisis harga satuan (mencakup biaya bahan, upah, dan alat).','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Struktur rincian kerja atau Work Breakdown Structure (WBS) dibuat dengan tujuan untuk...','[{"key": "A", "text": "Menghitung total biaya proyek secara langsung"}, {"key": "B", "text": "Memecah proyek menjadi bagian-bagian yang lebih kecil dan mudah dikelola"}, {"key": "C", "text": "Menentukan siapa manajer proyek yang bertanggung jawab"}, {"key": "D", "text": "Mengalokasikannya dana untuk setiap pekerja"}]'::jsonb,'A','Kurva S adalah representasi grafis dari kemajuan proyek kumulatif dari waktu ke waktu. Sumbu horizontalnya adalah waktu (hari, minggu, bulan), dan sumbu vertikalnya adalah persentase kemajuan kumulatif (biasanya berdasarkan biaya atau bobot pekerjaan). Bentuk kurva yang menyerupai huruf ''S'' mencerminkan laju proyek yang lambat di awal, cepat di pertengahan, dan melambat kembali di akhir.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Gaji manajer proyek dan sewa kantor proyek termasuk dalam kategori...','[{"key": "A", "text": "Biaya langsung (direct cost)"}, {"key": "B", "text": "Biaya tidak langsung (indirect cost)"}, {"key": "C", "text": "Biaya material"}, {"key": "D", "text": "Biaya peralatan"}]'::jsonb,'A','Dalam metode CPM, jalur kritis didefinisikan sebagai urutan kegiatan yang menentukan durasi total proyek. Ini adalah jalur terpanjang melalui jaringan kerja proyek. Ciri utama dari setiap kegiatan yang berada di jalur kritis adalah mereka tidak memiliki kelonggaran waktu atau float (sering juga disebut slack). Artinya, setiap keterlambatan pada salah satu kegiatan di jalur ini akan secara langsung menyebabkan keterlambatan pada tanggal penyelesaian akhir proyek.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam survei pemetaan, titik yang memiliki koordinat dan/atau ketinggian yang sudah diketahui secara pasti dan digunakan sebagai acuan disebut...','[{"key": "A", "text": "Titik poligon"}, {"key": "B", "text": "Titik detail"}, {"key": "C", "text": "Titik ikat"}, {"key": "D", "text": "Titik kontrol (Benchmark)"}]'::jsonb,'A','Gardu induk PLN berisi peralatan listrik yang sangat berat dan sensitif, seperti transformator daya. Peralatan ini memerlukan struktur pondasi beton bertulang yang masif, dirancang dengan presisi untuk menahan berat, getaran, dan beban lainnya. Biaya untuk pekerjaan sipil pondasi-pondasi ini, bersama dengan pondasi untuk gedung kontrol, seringkali menjadi komponen biaya terbesar dalam pekerjaan sipil pembangunan gardu.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada peta kontur, garis-garis kontur yang rapat menunjukkan bahwa area tersebut...','[{"key": "A", "text": "Datar"}, {"key": "B", "text": "Landai"}, {"key": "C", "text": "Curam"}, {"key": "D", "text": "Berupa perairan"}]'::jsonb,'A','Metode PERT dikembangkan untuk mengelola proyek di mana terdapat ketidakpastian yang tinggi mengenai durasi masing-masing kegiatan. Alih-alih menggunakan satu estimasi waktu, PERT menggunakan tiga estimasi: waktu optimis (jika semua berjalan lancar), waktu paling mungkin (kondisi normal), dan waktu pesimis (jika terjadi banyak masalah). Ketiga estimasi ini kemudian digunakan untuk menghitung durasi yang diharapkan dan probabilitas penyelesaian proyek.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari survei topografi adalah untuk...','[{"key": "A", "text": "Menentukan batas-batas kepemilikan tanah"}, {"key": "B", "text": "Mengukur luas tanah untuk keperluan pajak"}, {"key": "C", "text": "Mengumpulkan data bentuk permukaan bumi dan lokasinya"}, {"key": "D", "text": "Menentukan jenis batuan di bawah permukaan"}]'::jsonb,'A','Work Breakdown Structure (WBS) adalah fondasi dari perencanaan proyek. Ini adalah proses memecah lingkup kerja proyek yang besar dan kompleks menjadi bagian-bagian yang lebih kecil, spesifik, dan dapat dikelola, yang disebut paket kerja (work packages). Dengan WBS, estimasi biaya, penjadwalan, dan penugasan tanggung jawab menjadi jauh lebih mudah dan akurat.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Mengapa pemetaan kontur sangat penting dalam perencanaan jalur transmisi listrik?','[{"key": "A", "text": "Untuk menentukan warna tiang tower"}, {"key": "B", "text": "Untuk menemukan rute terpendek dengan topografi yang efisien untuk konstruksi"}, {"key": "C", "text": "Untuk menghitung jumlah penduduk di sepanjang jalur"}, {"key": "D", "text": "Untuk menentukan jenis kabel yang akan digunakan"}]'::jsonb,'A','Biaya proyek dibagi menjadi dua kategori besar. Biaya langsung adalah biaya yang dapat diatribusikan secara spesifik ke suatu item pekerjaan, seperti biaya material dan upah pekerja di lapangan. Sementara itu, biaya tidak langsung (atau overhead) adalah biaya yang diperlukan untuk menjalankan proyek secara keseluruhan tetapi tidak terikat pada satu pekerjaan spesifik, contohnya adalah gaji staf manajemen, sewa kantor, dan biaya administrasi.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Skala peta 1:500 berarti bahwa...','[{"key": "A", "text": "1 cm di peta sama dengan 500 cm (5 meter) di lapangan"}, {"key": "B", "text": "1 cm di peta sama dengan 500 meter di lapangan"}, {"key": "C", "text": "1 cm di peta sama dengan 500 km di lapangan"}, {"key": "D", "text": "500 cm di peta sama dengan 1 cm di lapangan"}]'::jsonb,'A','','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Alat survei modern yang dapat mengukur sudut horizontal, sudut vertikal, dan jarak secara elektronik dalam satu unit adalah...','[{"key": "A", "text": "Waterpass"}, {"key": "B", "text": "Theodolite"}, {"key": "C", "text": "Kompas"}, {"key": "D", "text": "Total Station"}]'::jsonb,'A','Titik kontrol, yang sering disebut Bench Mark (BM) untuk referensi ketinggian (vertikal) atau Titik Kontrol Dasar Teknik (TKDT) untuk referensi posisi (horizontal), adalah titik permanen di lapangan yang koordinat dan/atau elevasinya telah ditentukan secara akurat melalui pengukuran presisi. Titik-titik ini berfungsi sebagai titik referensi atau titik ikat yang stabil untuk semua kegiatan survei dan pemetaan selanjutnya di area proyek.','AKDING',40);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Lendutan (deflection) maksimum pada balok sederhana yang dibebani beban terpusat tepat di tengah bentang terjadi di...','[{"key": "A", "text": "Tumpuan"}, {"key": "B", "text": "Seperempat bentang"}, {"key": "C", "text": "Tengah bentang"}, {"key": "D", "text": "Lokasi acak"}]'::jsonb,'A','Lendutan atau defleksi adalah perpindahan vertikal suatu titik pada balok akibat pembebanan. Untuk kasus balok sederhana yang ditumpu di kedua ujung dan menerima beban terpusat tepat di tengah, lengkungan balok akan simetris. Titik dengan lendutan terbesar secara intuitif dan matematis berada tepat di bawah titik di mana beban tersebut bekerja, yaitu di tengah bentang.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perbandingan antara perubahan panjang suatu benda terhadap panjang awalnya akibat gaya yang bekerja disebut...','[{"key": "A", "text": "Tegangan (Stress)"}, {"key": "B", "text": "Regangan (Strain)"}, {"key": "C", "text": "Modulus Elastisitas"}, {"key": "D", "text": "Momen Inersia"}]'::jsonb,'A','Regangan adalah ukuran deformasi atau perubahan bentuk suatu material. Secara spesifik, regangan normal didefinisikan sebagai perubahan panjang per satuan panjang awal. Regangan merupakan besaran tak berdimensi dan merupakan respons material terhadap tegangan (stress) yang bekerja padanya.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fenomena kegagalan struktur pada kolom langsing yang mengalami beban tekan aksial, di mana kolom tiba-tiba melengkung secara lateral disebut...','[{"key": "A", "text": "Kelelehan (Yielding)"}, {"key": "B", "text": "Geser (Shear)"}, {"key": "C", "text": "Tekuk (Buckling)"}, {"key": "D", "text": "Puntir (Torsion)"}]'::jsonb,'A','Tekuk adalah modus kegagalan yang khas pada elemen struktur yang langsing (panjangnya jauh lebih besar dari dimensi penampangnya) saat menerima beban tekan. Alih-alih hancur karena materialnya mencapai batas kuat tekan, elemen tersebut tiba-tiba kehilangan stabilitas dan melengkung ke samping. Ini merupakan pertimbangan desain yang sangat penting untuk kolom dan elemen tekan pada menara.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam desain struktur menara transmisi, kombinasi pembebanan yang harus ditinjau umumnya mencakup...','[{"key": "A", "text": "Hanya beban mati dan beban hidup"}, {"key": "B", "text": "Hanya beban angin dan beban gempa"}, {"key": "C", "text": "Kombinasi beban mati, beban hidup, beban angin, dan beban lainnya"}, {"key": "D", "text": "Hanya berat sendiri struktur"}]'::jsonb,'A','Desain struktur yang aman mengharuskan analisis terhadap berbagai kemungkinan kondisi pembebanan yang paling kritis. Standar desain (seperti SNI) mensyaratkan penggunaan kombinasi pembebanan, yang menggabungkan berbagai jenis beban (beban mati/berat sendiri, beban hidup, beban angin, beban gempa, dll.) dengan faktor beban tertentu untuk mendapatkan kondisi tegangan maksimum pada struktur.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Hukum Hooke menyatakan bahwa hubungan antara tegangan dan regangan pada material elastis bersifat...','[{"key": "A", "text": "Non-linier"}, {"key": "B", "text": "Linier"}, {"key": "C", "text": "Eksponensial"}, {"key": "D", "text": "Kuadratik"}]'::jsonb,'A','Hukum Hooke adalah prinsip dasar dalam elastisitas material yang menyatakan bahwa untuk deformasi yang relatif kecil, besarnya regangan yang dialami suatu material berbanding lurus (linier) dengan besarnya tegangan yang diberikan. Konstanta proporsionalitas antara tegangan dan regangan ini dikenal sebagai Modulus Elastisitas atau Modulus Young.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Gaya internal pada elemen struktur yang cenderung memutar atau melintir elemen tersebut terhadap sumbu longitudinalnya disebut...','[{"key": "A", "text": "Gaya geser"}, {"key": "B", "text": "Momen lentur"}, {"key": "C", "text": "Gaya aksial"}, {"key": "D", "text": "Torsi"}]'::jsonb,'A','Torsi atau momen puntir adalah gaya internal yang timbul ketika suatu elemen struktur (seperti poros atau balok) dibebani oleh momen yang bekerja sejajar dengan sumbu longitudinalnya. Gaya ini menyebabkan penampang elemen berputar atau melintir relatif satu sama lain.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Suatu struktur dikatakan dalam kondisi setimbang (equilibrium) jika...','[{"key": "A", "text": "Total gaya yang bekerja lebih besar dari nol"}, {"key": "B", "text": "Total momen yang bekerja lebih besar dari nol"}, {"key": "C", "text": "Total resultan gaya dan total resultan momen yang bekerja sama dengan nol"}, {"key": "D", "text": "Struktur tidak mengalami deformasi"}]'::jsonb,'A','Prinsip kesetimbangan statis menyatakan bahwa agar suatu benda atau struktur tetap diam (tidak bergerak atau berotasi), maka semua gaya dan momen yang bekerja padanya harus saling meniadakan. Ini dirumuskan dalam tiga persamaan: jumlah gaya dalam arah X sama dengan nol (ΣFx=0), jumlah gaya dalam arah Y sama dengan nol (ΣFy=0), dan jumlah momen terhadap titik manapun sama dengan nol (ΣM=0).','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi utama dari selimut beton (concrete cover) pada elemen beton bertulang adalah...','[{"key": "A", "text": "Menambah kekuatan tekan beton"}, {"key": "B", "text": "Melindungi baja tulangan dari korosi dan api"}, {"key": "C", "text": "Mengurangi berat total struktur"}, {"key": "D", "text": "Memudahkan proses pengecoran"}]'::jsonb,'A','','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perbedaan mendasar antara mutu beton fc'' (uji silinder) dan K (uji kubus) adalah...','[{"key": "A", "text": "Umur pengujian beton"}, {"key": "B", "text": "Bentuk benda uji dan standar konversinya"}, {"key": "C", "text": "Jenis semen yang digunakan"}, {"key": "D", "text": "Suhu pada saat pengujian"}]'::jsonb,'A','Selimut beton adalah lapisan beton terluar yang membungkus baja tulangan. Fungsinya sangat krusial; pertama, ia menjadi penghalang fisik yang mencegah agen korosif seperti air dan klorida mencapai permukaan baja. Kedua, dalam kasus kebakaran, selimut beton bertindak sebagai isolator termal yang memperlambat laju kenaikan suhu pada baja tulangan, sehingga struktur tidak cepat runtuh.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sambungan lewatan (lap splice) pada baja tulangan bertujuan untuk...','[{"key": "A", "text": "Menghentikan tulangan di tengah bentang"}, {"key": "B", "text": "Menyambung dua batang tulangan untuk mencapai panjang yang diinginkan"}, {"key": "C", "text": "Menahan gaya geser pada balok"}, {"key": "D", "text": "Mengurangi jumlah tulangan yang dibutuhkan"}]'::jsonb,'A','Mutu beton fc'' (misalnya fc'' 25 MPa) ditentukan dari hasil pengujian tekan benda uji berbentuk silinder (diameter 15 cm, tinggi 30 cm). Sementara itu, mutu beton K (misalnya K-300 kg/cm²) ditentukan dari uji tekan benda uji berbentuk kubus (sisi 15 cm). Karena perbedaan bentuk dan distribusi tegangan saat pengujian, terdapat hubungan konversi empiris antara keduanya (misalnya, fc'' ≈ 0.83 K).','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jenis profil baja yang paling umum digunakan sebagai elemen rangka batang pada struktur tower transmisi PLN adalah...','[{"key": "A", "text": "Baja IWF (Wide Flange)"}, {"key": "B", "text": "Baja Kanal (Channel)"}, {"key": "C", "text": "Baja Siku (Angle)"}, {"key": "D", "text": "Baja Hollow (Pipa Kotak)"}]'::jsonb,'A','Panjang standar baja tulangan dari pabrik terbatas (biasanya 12 meter). Untuk elemen struktur yang lebih panjang seperti kolom tinggi atau balok bentang panjang, diperlukan penyambungan. Sambungan lewatan adalah metode di mana dua batang tulangan dipasang berdampingan (saling tumpang tindih) sepanjang jarak tertentu (panjang penyaluran) sehingga transfer gaya tarik atau tekan dari satu batang ke batang lainnya dapat terjadi melalui lekatan dengan beton di sekelilingnya.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fenomena rangkak (creep) pada beton adalah...','[{"key": "A", "text": "Penyusutan volume akibat kehilangan air"}, {"key": "B", "text": "Deformasi yang bertambah seiring waktu akibat beban tetap"}, {"key": "C", "text": "Retak yang terjadi akibat suhu tinggi"}, {"key": "D", "text": "Penambahan kekuatan beton seiring umur"}]'::jsonb,'A','Struktur menara transmisi listrik (sutet) umumnya merupakan struktur rangka batang (truss). Profil baja siku (L-shape) sangat ideal untuk aplikasi ini karena mudah disambung menggunakan baut pada pelat buhul (gusset plate), efisien dalam menahan gaya tarik maupun tekan, dan relatif ekonomis serta mudah didapatkan.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rasio air-semen (water-cement ratio) pada adukan beton sangat mempengaruhi kekuatan. Jika rasio air-semen semakin tinggi, maka kekuatan beton cenderung...','[{"key": "A", "text": "Meningkat"}, {"key": "B", "text": "Menurun"}, {"key": "C", "text": "Tidak berubah"}, {"key": "D", "text": "Meningkat lalu menurun"}]'::jsonb,'A','Rangkak (creep) adalah sifat beton di mana regangannya terus bertambah seiring berjalannya waktu meskipun beban yang bekerja padanya konstan. Ini adalah deformasi yang bergantung pada waktu dan disebabkan oleh pergerakan air di dalam pasta semen yang mengeras dan penyesuaian mikrostruktur internal akibat tegangan berkelanjutan.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam fabrikasi struktur baja, metode penyambungan yang menggunakan baut mutu tinggi untuk menjepit dua atau lebih pelat baja disebut...','[{"key": "A", "text": "Sambungan Las (Welded Connection)"}, {"key": "B", "text": "Sambungan Baut (Bolted Connection)"}, {"key": "C", "text": "Sambungan Paku Keling (Riveted Connection)"}, {"key": "D", "text": "Sambungan Pin (Pinned Connection)"}]'::jsonb,'A','Rasio air-semen adalah faktor paling penting yang mengontrol kekuatan beton. Air diperlukan untuk reaksi kimia (hidrasi) dengan semen. Namun, air yang berlebih dari yang dibutuhkan akan menguap dan meninggalkan pori-pori di dalam beton. Semakin banyak pori, semakin rendah kepadatan dan kekuatan beton. Oleh karena itu, rasio air-semen yang lebih tinggi akan menghasilkan beton dengan kekuatan yang lebih rendah.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tegangan efektif dalam mekanika tanah didefinisikan sebagai...','[{"key": "A", "text": "Tegangan total dikurangi tekanan air pori"}, {"key": "B", "text": "Tekanan air pori dikurangi tegangan total"}, {"key": "C", "text": "Tegangan total dibagi tekanan air pori"}, {"key": "D", "text": "Penjumlahan tegangan total dan tekanan air pori"}]'::jsonb,'A','Sambungan baut, terutama yang menggunakan baut mutu tinggi, adalah metode penyambungan yang sangat umum dalam konstruksi baja, khususnya untuk struktur seperti menara transmisi yang seringkali dirakit di lapangan. Baut bekerja dengan menjepit elemen-elemen yang disambung, dan gaya ditransfer melalui gesekan antara permukaan atau melalui daya dukung baut itu sendiri.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jenis penurunan (settlement) pondasi yang terjadi segera setelah beban diterapkan, tanpa ada perubahan volume tanah, disebut...','[{"key": "A", "text": "Penurunan konsolidasi primer"}, {"key": "B", "text": "Penurunan segera (immediate settlement)"}, {"key": "C", "text": "Penurunan konsolidasi sekunder"}, {"key": "D", "text": "Penurunan diferensial"}]'::jsonb,'A','','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Gaya seret ke bawah yang bekerja pada tiang pancang akibat penurunan tanah di sekelilingnya disebut...','[{"key": "A", "text": "Gaya apung (buoyancy)"}, {"key": "B", "text": "Daya dukung ujung (end bearing)"}, {"key": "C", "text": "Gesekan selimut negatif (negative skin friction)"}, {"key": "D", "text": "Tekanan tanah lateral"}]'::jsonb,'A','Konsep tegangan efektif yang diperkenalkan oleh Karl Terzaghi adalah prinsip fundamental dalam mekanika tanah. Tegangan total (σ) pada suatu titik di dalam tanah disebabkan oleh berat tanah dan beban di atasnya. Sebagian dari tegangan ini dipikul oleh air di dalam pori (tekanan air pori, u). Sisanya, yang merupakan tegangan kontak antar butiran tanah, disebut tegangan efektif (σ''). Tegangan inilah yang mengontrol kekuatan dan perilaku deformasi tanah.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk meningkatkan daya dukung tanah lunak di lokasi pondasi tower transmisi, salah satu metode perbaikan tanah (ground improvement) yang dapat digunakan adalah...','[{"key": "A", "text": "Penggalian dan pembuangan seluruh tanah lunak"}, {"key": "B", "text": "Penggunaan geosintetik atau pemasangan PVD (Prefabricated Vertical Drain)"}, {"key": "C", "text": "Penambahan air pada tanah"}, {"key": "D", "text": "Mengurangi beban tower"}]'::jsonb,'A','Penurunan segera, atau disebut juga penurunan elastis, terjadi pada semua jenis tanah sesaat setelah beban diterapkan. Penurunan ini disebabkan oleh deformasi elastis dari massa tanah di bawah pondasi, terjadi tanpa adanya perubahan volume atau kadar air. Pada tanah granular (pasir), jenis penurunan ini merupakan komponen utama dari total penurunan.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Faktor kapasitas dukung tanah (bearing capacity factors) Nc, Nq, dan Nγ dalam rumus Terzaghi bergantung pada nilai...','[{"key": "A", "text": "Kohesi tanah (c)"}, {"key": "B", "text": "Sudut geser dalam tanah (φ)"}, {"key": "C", "text": "Berat volume tanah (γ)"}, {"key": "D", "text": "Lebar pondasi (B)"}]'::jsonb,'A','Jika tanah di sekitar tiang pancang mengalami penurunan (misalnya karena konsolidasi atau penimbunan baru), tanah tersebut akan "menggantung" pada tiang dan menariknya ke bawah. Gaya gesek yang arahnya ke bawah ini disebut gesekan selimut negatif. Gaya ini bekerja sebagai beban tambahan pada tiang dan harus diperhitungkan dalam desain karena mengurangi kapasitas dukung tiang.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pengujian laboratorium untuk menentukan parameter kekuatan geser tanah (kohesi dan sudut geser dalam) secara akurat adalah...','[{"key": "A", "text": "Uji batas-batas Atterberg"}, {"key": "B", "text": "Uji hidrometer"}, {"key": "C", "text": "Uji triaksial"}, {"key": "D", "text": "Uji pemadatan (Proctor)"}]'::jsonb,'A','PVD adalah metode perbaikan tanah lunak (lempung jenuh) yang bekerja dengan cara mempercepat proses konsolidasi. Drainase vertikal buatan ini dipasang ke dalam tanah, menciptakan jalur pendek bagi air pori untuk keluar ke permukaan saat beban (biasanya berupa timbunan sementara) diterapkan. Dengan keluarnya air pori lebih cepat, tanah menjadi lebih padat dan kekuatannya meningkat dalam waktu yang lebih singkat.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Klasifikasi tanah berdasarkan ukuran butir membagi tanah menjadi kategori utama yaitu...','[{"key": "A", "text": "Tanah organik dan anorganik"}, {"key": "B", "text": "Tanah jenuh dan tidak jenuh"}, {"key": "C", "text": "Tanah kohesif dan non-kohesif (granular)"}, {"key": "D", "text": "Tanah keras dan tanah lunak"}]'::jsonb,'A','Faktor kapasitas dukung Nc, Nq, dan Nγ adalah koefisien tak berdimensi yang digunakan dalam persamaan kapasitas dukung pondasi dangkal. Nilai dari ketiga faktor ini secara eksklusif merupakan fungsi dari sudut geser dalam (φ) tanah. Nilai kohesi (c) dan berat volume (γ) masuk ke dalam komponen lain dari persamaan tersebut, bukan untuk menentukan nilai faktor-faktor ini.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Lonjakan air yang terjadi ketika aliran superkritis berubah secara tiba-tiba menjadi aliran subkritis disebut...','[{"key": "A", "text": "Aliran laminar"}, {"key": "B", "text": "Aliran turbulen"}, {"key": "C", "text": "Loncatan hidraulik (hydraulic jump)"}, {"key": "D", "text": "Pusaran air (vortex)"}]'::jsonb,'A','Uji triaksial dianggap sebagai metode pengujian laboratorium yang paling andal untuk menentukan parameter kekuatan geser tanah (c dan φ). Dalam pengujian ini, sampel tanah silindris diberikan tekanan keliling (confining pressure) dan kemudian diberikan beban aksial hingga runtuh. Dengan melakukan pengujian pada beberapa tingkat tekanan keliling yang berbeda, kurva selubung keruntuhan Mohr-Coulomb dapat digambar untuk mendapatkan nilai c dan φ.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Bangunan air yang berfungsi sebagai "dinding" pelimpah di saluran terbuka untuk mengukur debit atau mengontrol tinggi muka air disebut...','[{"key": "A", "text": "Pintu air (gate)"}, {"key": "B", "text": "Gorong-gorong (culvert)"}, {"key": "C", "text": "Ambang (weir)"}, {"key": "D", "text": "Talang (flume)"}]'::jsonb,'A','Secara fundamental, perilaku mekanis tanah sangat ditentukan oleh ukuran partikelnya. Tanah berbutir kasar seperti kerikil dan pasir, di mana kekuatan utamanya berasal dari gesekan antar partikel, digolongkan sebagai tanah non-kohesif atau granular. Tanah berbutir halus seperti lanau dan lempung, di mana daya lekat (kohesi) antar partikel berperan penting, digolongkan sebagai tanah kohesif.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Garis yang merepresentasikan total energi (energi ketinggian + energi tekanan + energi kecepatan) per satuan berat air di sepanjang aliran disebut...','[{"key": "A", "text": "Garis muka air"}, {"key": "B", "text": "Garis gradien hidraulik (HGL)"}, {"key": "C", "text": "Garis gradien energi (EGL)"}, {"key": "D", "text": "Garis dasar saluran"}]'::jsonb,'A','','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses pengikisan atau gerusan lokal pada dasar sungai atau kanal di sekitar pilar jembatan atau pondasi bangunan air disebut...','[{"key": "A", "text": "Sedimentasi"}, {"key": "B", "text": "Aggradasi"}, {"key": "C", "text": "Scouring"}, {"key": "D", "text": "Abrasi"}]'::jsonb,'A','Loncatan hidraulik adalah fenomena di mana aliran yang sangat cepat dan dangkal (superkritis) tiba-tiba berubah menjadi aliran yang lambat dan dalam (subkritis). Perubahan ini disertai dengan turbulensi yang hebat dan kehilangan energi yang signifikan. Fenomena ini sering dimanfaatkan dalam desain bangunan air, seperti di hilir bendungan, untuk meredam energi aliran yang berkecepatan tinggi.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam analisis aliran di saluran terbuka, energi spesifik didefinisikan sebagai...','[{"key": "A", "text": "Total energi aliran"}, {"key": "B", "text": "Energi aliran per satuan lebar saluran"}, {"key": "C", "text": "Energi aliran terhadap dasar saluran (jumlah kedalaman dan head kecepatan)"}, {"key": "D", "text": "Energi kinetik aliran saja"}]'::jsonb,'A','Ambang adalah struktur atau bendung kecil yang dibangun melintang di sebuah saluran terbuka. Air akan melimpas di atas puncak (crest) ambang. Dengan mengukur ketinggian air di atas puncak ambang, dan menggunakan rumus empiris yang sesuai dengan bentuk ambang (misalnya, ambang tajam, ambang lebar), debit aliran di saluran tersebut dapat dihitung.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kehilangan energi (head loss) pada aliran air di kanal PLTA dapat disebabkan oleh...','[{"key": "A", "text": "Hanya oleh kemiringan dasar saluran"}, {"key": "B", "text": "Hanya oleh kecepatan aliran"}, {"key": "C", "text": "Gesekan dengan dinding/dasar saluran dan perubahan geometri (minor losses)"}, {"key": "D", "text": "Suhu air"}]'::jsonb,'A','Garis gradien energi atau Energy Grade Line (EGL) adalah representasi grafis dari total energi mekanik aliran. Elevasi EGL pada suatu titik adalah jumlah dari elevasi dasar saluran (head potensial), kedalaman air (head tekanan), dan head kecepatan (v²/2g). Dalam aliran nyata, EGL akan selalu menurun searah aliran karena adanya kehilangan energi akibat gesekan.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dokumen yang berisi rincian kuantitas atau volume dari seluruh item pekerjaan dalam suatu proyek konstruksi disebut...','[{"key": "A", "text": "Spesifikasi Teknis"}, {"key": "B", "text": "Gambar Kerja"}, {"key": "C", "text": "Bill of Quantities (BQ)"}, {"key": "D", "text": "Jadwal Proyek"}]'::jsonb,'A','Scouring adalah proses erosi atau pengikisan sedimen (pasir, kerikil) dari dasar dan tepi sungai yang disebabkan oleh aliran air. Ketika aliran air terhalang oleh struktur seperti pilar jembatan atau pondasi, kecepatan aliran di sekitar struktur tersebut meningkat dan membentuk pusaran air yang kuat, yang mampu menggerus material dasar sungai dan dapat membahayakan stabilitas pondasi struktur.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam metode manajemen nilai hasil (Earned Value Management), jika Cost Performance Index (CPI) bernilai kurang dari 1, maka proyek tersebut...','[{"key": "A", "text": "Lebih cepat dari jadwal"}, {"key": "B", "text": "Sesuai dengan anggaran"}, {"key": "C", "text": "Lebih lambat dari jadwal"}, {"key": "D", "text": "Melebihi anggaran (over budget)"}]'::jsonb,'A','Energi spesifik (E) adalah konsep yang berguna dalam analisis aliran saluran terbuka. Ini didefinisikan sebagai total energi aliran yang diukur relatif terhadap titik terendah di dasar saluran. Dengan demikian, nilainya adalah jumlah dari kedalaman aliran (y) dan head kecepatan (v²/2g). Konsep ini digunakan untuk menganalisis perubahan kedalaman aliran, seperti pada loncatan hidraulik.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Teknik manajemen sumber daya untuk mengatasi keterbatasan jumlah sumber daya dengan cara menggeser kegiatan non-kritis tanpa mengubah durasi proyek disebut...','[{"key": "A", "text": "Crashing"}, {"key": "B", "text": "Fast Tracking"}, {"key": "C", "text": "Resource Leveling"}, {"key": "D", "text": "Resource Smoothing"}]'::jsonb,'A','Kehilangan energi dalam aliran saluran terbuka terdiri dari dua komponen. Kehilangan energi utama (major losses) disebabkan oleh gesekan yang terus-menerus antara air yang mengalir dengan permukaan dasar dan dinding saluran. Kehilangan energi minor (minor losses) terjadi secara lokal akibat adanya perubahan geometri saluran seperti belokan, penyempitan, pelebaran, atau adanya bangunan air.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Biaya tak terduga (contingency cost) dalam estimasi biaya proyek dialokasikan untuk...','[{"key": "A", "text": "Keuntungan kontraktor"}, {"key": "B", "text": "Gaji manajer proyek"}, {"key": "C", "text": "Risiko yang teridentifikasi (known unknowns)"}, {"key": "D", "text": "Pembelian material utama"}]'::jsonb,'A','','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perbedaan utama antara diagram batang (Gantt Chart) dan diagram jaringan kerja (CPM/PERT) adalah...','[{"key": "A", "text": "Gantt chart lebih sulit dibuat"}, {"key": "B", "text": "Diagram jaringan kerja tidak menunjukkan durasi kegiatan"}, {"key": "C", "text": "Diagram jaringan kerja menunjukkan hubungan ketergantungan antar kegiatan, sedangkan Gantt chart tidak secara eksplisit"}, {"key": "D", "text": "Gantt chart hanya digunakan untuk proyek kecil"}]'::jsonb,'A','Bill of Quantities, sering juga disebut Daftar Kuantitas dan Harga, adalah dokumen tender yang merinci semua item pekerjaan, deskripsi singkat, satuan, dan kuantitas (volume) yang diperlukan untuk menyelesaikan proyek. Kontraktor akan mengisi harga satuan dan total harga untuk setiap item, yang kemudian menjadi dasar penawaran harga kontrak.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis SWOT (Strengths, Weaknesses, Opportunities, Threats) dalam manajemen proyek digunakan pada tahap...','[{"key": "A", "text": "Pelaksanaan"}, {"key": "B", "text": "Penutupan proyek"}, {"key": "C", "text": "Perencanaan strategis dan identifikasi risiko"}, {"key": "D", "text": "Pengendalian mutu"}]'::jsonb,'A','Cost Performance Index (CPI) adalah rasio antara nilai pekerjaan yang telah diselesaikan (Earned Value, EV) dengan biaya aktual yang telah dikeluarkan (Actual Cost, AC). CPI = EV / AC. Jika CPI < 1, itu berarti biaya yang dikeluarkan lebih besar daripada nilai pekerjaan yang dihasilkan, yang menunjukkan bahwa kinerja biaya proyek buruk atau melebihi anggaran.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Metode estimasi biaya yang dilakukan pada tahap awal proyek dengan tingkat akurasi yang masih rendah, biasanya berdasarkan data historis dari proyek serupa, disebut...','[{"key": "A", "text": "Estimasi Detail"}, {"key": "B", "text": "Estimasi Konseptual atau Perkiraan Kasar"}, {"key": "C", "text": "Analisis Harga Satuan"}, {"key": "D", "text": "Estimasi Biaya Langsung"}]'::jsonb,'A','Resource smoothing adalah teknik penjadwalan yang bertujuan untuk meratakan penggunaan sumber daya dari waktu ke waktu agar tidak terjadi puncak dan lembah yang ekstrem. Hal ini dilakukan dengan memanfaatkan waktu luang (float) dari kegiatan-kegiatan non-kritis untuk menggeser jadwalnya, tanpa mengubah tanggal penyelesaian akhir proyek. Ini berbeda dari resource leveling yang boleh memperpanjang durasi proyek jika sumber daya benar-benar tidak tersedia.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Metode penentuan posisi suatu titik dengan cara mengukur sudut-sudut dari titik-titik yang sudah diketahui posisinya (membentuk jaringan segitiga) disebut...','[{"key": "A", "text": "Poligon"}, {"key": "B", "text": "Sipat Datar (Levelling)"}, {"key": "C", "text": "Triangulasi"}, {"key": "D", "text": "Pengikatan ke Muka"}]'::jsonb,'A','Biaya tak terduga adalah sejumlah dana yang dicadangkan dalam anggaran proyek untuk menutupi biaya-biaya yang mungkin timbul dari kejadian atau risiko yang telah diidentifikasi tetapi dampaknya tidak dapat diperkirakan secara pasti. Contohnya adalah kemungkinan kondisi tanah yang lebih buruk dari perkiraan atau cuaca ekstrem. Ini berbeda dari cadangan manajemen yang untuk risiko yang tidak teridentifikasi.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perhitungan volume galian dan timbunan (cut and fill) untuk pembangunan jalan akses ke lokasi PLTA paling efisien dilakukan dengan menggunakan data dari...','[{"key": "A", "text": "Peta geologi"}, {"key": "B", "text": "Peta tata guna lahan"}, {"key": "C", "text": "Peta kontur (topografi)"}, {"key": "D", "text": "Foto udara"}]'::jsonb,'A','Keunggulan utama diagram jaringan kerja (seperti diagram panah atau preseden dalam metode CPM/PERT) adalah kemampuannya untuk secara visual dan logis menunjukkan hubungan ketergantungan (precedence) antar semua kegiatan dalam proyek. Sementara Gantt chart sangat baik untuk visualisasi jadwal terhadap kalender, ia tidak secara inheren menampilkan hubungan logika ini, meskipun versi modernnya dapat menambahkan garis-garis ketergantungan.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sudut horizontal yang diukur searah jarum jam dari arah Utara referensi ke suatu garis target disebut...','[{"key": "A", "text": "Bearing"}, {"key": "B", "text": "Azimuth"}, {"key": "C", "text": "Sudut Inklinasi"}, {"key": "D", "text": "Sudut Jurusan"}]'::jsonb,'A','Analisis SWOT adalah alat perencanaan strategis yang digunakan untuk mengevaluasi Kekuatan (Strengths), Kelemahan (Weaknesses), Peluang (Opportunities), dan Ancaman (Threats) yang terkait dengan suatu proyek atau organisasi. Dalam konteks manajemen proyek, ini sangat berguna pada tahap awal perencanaan untuk mengidentifikasi faktor internal dan eksternal yang dapat mempengaruhi keberhasilan proyek, termasuk sebagai dasar untuk identifikasi risiko.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sistem proyeksi peta yang umum digunakan dalam pemetaan skala besar di Indonesia, yang membagi bumi menjadi 60 zona, adalah...','[{"key": "A", "text": "Proyeksi Mercator"}, {"key": "B", "text": "Proyeksi Kerucut"}, {"key": "C", "text": "Proyeksi Universal Transverse Mercator (UTM)"}, {"key": "D", "text": "Proyeksi Gnomonic"}]'::jsonb,'A','Pada tahap paling awal proyek (tahap studi kelayakan atau konseptual), di mana detail desain belum tersedia, estimasi biaya dibuat dengan tingkat akurasi yang rendah (misalnya ±25-50%). Metode ini, yang disebut estimasi konseptual atau rough order of magnitude (ROM) estimate, biasanya didasarkan pada parameter biaya dari proyek-proyek serupa di masa lalu (misalnya, biaya per kilometer untuk jalur transmisi atau biaya per megawatt untuk gardu induk).','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pengukuran sipat datar (levelling) adalah proses survei yang bertujuan utama untuk menentukan...','[{"key": "A", "text": "Koordinat horizontal (X,Y) suatu titik"}, {"key": "B", "text": "Luas suatu area"}, {"key": "C", "text": "Beda tinggi atau elevasi antara titik-titik"}, {"key": "D", "text": "Arah kiblat"}]'::jsonb,'A','','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam teknologi survei modern, sistem satelit yang digunakan untuk menentukan posisi presisi di permukaan bumi untuk pemetaan jalur transmisi adalah...','[{"key": "A", "text": "RADAR"}, {"key": "B", "text": "SONAR"}, {"key": "C", "text": "GNSS/GPS (Global Navigation Satellite System)"}, {"key": "D", "text": "LIDAR"}]'::jsonb,'A','Triangulasi adalah metode survei klasik untuk menentukan posisi titik-titik kontrol horizontal di area yang luas. Metode ini bekerja dengan mengukur panjang satu sisi awal (garis basis) secara sangat teliti, dan kemudian mengukur semua sudut dalam serangkaian segitiga yang saling berhubungan yang mencakup seluruh area. Posisi titik-titik lainnya kemudian dihitung secara trigonometri.','AKDING',40);
